choose.when:

(
    SELECT cc.* FROM ord_change cc WHERE upper(cc.no) LIKE #{keywordPrefix}
    OR upper(cc.no) IN #{code}
    UNION
    SELECT cc.* FROM ord_order ko JOIN ord_change cc ON cc.order_id = ko.id
    WHERE upper(ko.no) LIKE #{keywordPrefix}
    OR upper(ko.no) IN #{code}
    UNION
    SELECT cc.* FROM sty_style_sku ks JOIN ord_change_item ci ON ci.style_sku_id = ks.id
    JOIN ord_change cc ON cc.id = ci.change_id WHERE upper(ks.code) LIKE #{keywordPrefix}
    OR upper(ks.code) IN #{code}
)

mapper.sql:
WHERE true

    AND (o.create_by = #{scope.userId} OR o.sales_id = #{scope.userId} OR o.merch_id = #{scope.userId}
         OR c.create_by = #{scope.userId})


    AND c.status IN #{s}


    AND (c.status = 'DRAFT' AND c.reject_reason IS NOT NULL) = #{q.rejected}

AND c.order_id = #{q.orderId}
AND (',' || c.change_types || ',') LIKE '%,' || #{q.changeType} || ',%'

    AND c.create_time >= (CAST(#{q.createDateFrom} AS date)::timestamp AT TIME ZONE 'Asia/Shanghai')


    AND c.create_time < ((CAST(#{q.createDateTo} AS date) + 1)::timestamp AT TIME ZONE 'Asia/Shanghai')
